package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;
public class StudyFilesTest {
 static int n;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}
 public static void main(String[] args)throws Exception{File dir=Files.createTempDirectory("study-files").toFile();try{File target=new File(dir,"book.pdf");byte[] data="materials Álgebra".getBytes("UTF-8");String hash=StudyFiles.copy(new ByteArrayInputStream(data),target,100,()->false);ok(Arrays.equals(data,Files.readAllBytes(target.toPath())),"study import preserves source bytes");ok(hash.equals(StudyFiles.hash(target)),"study import SHA256 matches committed file");ok(!new File(target+".part").exists(),"study import leaves no partial after success");try{StudyFiles.copy(new ByteArrayInputStream(new byte[]{1}),target,100,()->false);throw new AssertionError();}catch(IOException e){ok(Arrays.equals(data,Files.readAllBytes(target.toPath())),"occupied study target is never overwritten");}File huge=new File(dir,"huge.pdf");try{StudyFiles.copy(new ByteArrayInputStream(new byte[101]),huge,100,()->false);throw new AssertionError();}catch(IOException e){ok(!huge.exists()&&!new File(huge+".part").exists(),"oversized import is rolled back");}File stop=new File(dir,"stop.pdf");try{StudyFiles.copy(new ByteArrayInputStream(data),stop,100,()->true);throw new AssertionError();}catch(InterruptedIOException e){ok(!stop.exists()&&!new File(stop+".part").exists(),"cancelled import leaves no partial material");}File broken=new File(dir,"broken.pdf");try{StudyFiles.copy(new InputStream(){public int read()throws IOException{throw new IOException("source gone");}},broken,100,()->false);throw new AssertionError();}catch(IOException e){ok(!broken.exists()&&!new File(broken+".part").exists(),"source read failure leaves no material");}ok(StudyFiles.extension("../../x.PDF").equals("pdf"),"only extension used from original filename");ok(StudyFiles.extension("x.abc/def").equals("bin"),"unsafe extension never enters storage path");ok(StudyFiles.extension("sem extensão").equals("bin"),"unknown extension has safe fallback");cancellationChecks(dir);archiveChecks(dir);System.out.println(n+" study import checks");}finally{for(File f:dir.listFiles())f.delete();dir.delete();}}
 static void cancellationChecks(File dir)throws Exception {
  File empty=new File(dir,"cancel-empty.pdf");
  try{StudyFiles.copy(new ByteArrayInputStream(new byte[0]),empty,100,()->true);throw new AssertionError("cancel empty");}
  catch(InterruptedIOException expected){ok(!empty.exists()&&!new File(empty+".part").exists(),"already-cancelled empty stream is not published");}
  File late=new File(dir,"cancel-at-eof.pdf");final boolean[] cancelled={false};
  InputStream input=new ByteArrayInputStream(new byte[]{1,2,3}){
   public synchronized int read(byte[] b,int off,int len){int n=super.read(b,off,len);if(n<0)cancelled[0]=true;return n;}
  };
  try{StudyFiles.copy(input,late,100,()->cancelled[0]);throw new AssertionError("late cancel");}
  catch(InterruptedIOException expected){ok(!late.exists()&&!new File(late+".part").exists(),"cancellation signalled at EOF keeps import unpublished");}
  File blocked=new File(dir,"occupied-part.pdf"),part=new File(blocked+".part");byte[] sentinel={7,8,9};Files.write(part.toPath(),sentinel);
  try{StudyFiles.copy(new ByteArrayInputStream(new byte[]{1}),blocked,100,()->false);throw new AssertionError("part conflict");}
  catch(IOException expected){ok(Arrays.equals(sentinel,Files.readAllBytes(part.toPath()))&&!blocked.exists(),"another import's staging file is preserved");}
  File dangling=new File(dir,"dangling-part.pdf"),link=new File(dangling+".part"),missing=new File(dir,"must-not-be-created");Files.createSymbolicLink(link.toPath(),missing.toPath());
  try{StudyFiles.copy(new ByteArrayInputStream(new byte[]{1}),dangling,100,()->false);throw new AssertionError("dangling part");}
  catch(IOException expected){ok(Files.isSymbolicLink(link.toPath())&&!missing.exists()&&!dangling.exists(),"dangling staging symlink is refused without writing its target");}
  File destination=new File(dir,"dangling-destination.pdf");Files.createSymbolicLink(destination.toPath(),missing.toPath());
  try{StudyFiles.copy(new ByteArrayInputStream(new byte[]{1}),destination,100,()->false);throw new AssertionError("dangling destination");}
  catch(IOException expected){ok(Files.isSymbolicLink(destination.toPath())&&!missing.exists(),"dangling destination symlink is treated as occupied");}
 }
 static File archive(File dir,String name,String... entries)throws Exception {File f=new File(dir,name);try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(new FileOutputStream(f))){for(String entry:entries){zip.putNextEntry(new java.util.zip.ZipEntry(entry));zip.write("{}".getBytes("UTF-8"));zip.closeEntry();}}return f;}
 static void rejected(File f,java.util.List<Long> ids,String label)throws Exception {try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(f)){try{StudyFiles.validateArchive(zip,ids);throw new AssertionError(label);}catch(IOException e){ok(true,label);}}}
 static void archiveChecks(File dir)throws Exception {File valid=archive(dir,"valid.zip","study.json","materials/1");try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(valid)){StudyFiles.validateArchive(zip,Arrays.asList(1L));ok(true,"portable study backup accepts exact manifest and material entries");}File empty=archive(dir,"empty.zip","study.json");try(java.util.zip.ZipFile zip=new java.util.zip.ZipFile(empty)){StudyFiles.validateArchive(zip,Collections.emptyList());ok(true,"empty material library backup accepted");}rejected(archive(dir,"traversal.zip","study.json","../escape"),Collections.emptyList(),"backup path traversal rejected");rejected(archive(dir,"absolute.zip","study.json","/absolute"),Collections.emptyList(),"backup absolute paths rejected");rejected(archive(dir,"missing.zip","study.json"),Arrays.asList(1L),"missing backup material rejected before database writes");rejected(archive(dir,"extra.zip","study.json","materials/1","materials/2"),Arrays.asList(1L),"unexpected backup material rejected");rejected(valid,Arrays.asList(1L,1L),"repeated manifest material ID rejected");rejected(valid,Arrays.asList(-1L),"negative manifest material ID rejected");}

}
